THEME = ("T06", "Contrôle d'accès par attributs et politiques (ABAC, PBAC, XACML)")
SOURCE = "NIST SP 800-162, « Guide to Attribute Based Access Control (ABAC) Definition and Considerations », 2014 ; OASIS XACML 3.0 (2013) ; NIST SP 800-178 (2016) ⚠ à vérifier"
Q = [
(1,"Sur quoi ABAC fonde-t-il la décision d'accès ?","Sur des attributs du sujet, de la ressource, de l'action et du contexte","Uniquement sur le nom de l'utilisateur","Uniquement sur le rôle","Uniquement sur l'adresse IP",
 "Les règles combinent des attributs : service, niveau, type de document, heure, lieu…"),
(1,"Quel est un exemple d'attribut du sujet ?","Son service d'appartenance","La taille du fichier","L'heure de la requête","Le type de document",
 "Les attributs du sujet décrivent la personne ou le processus : service, fonction, habilitation."),
(1,"Quel est un exemple d'attribut de la ressource ?","Sa classification","Le service du demandeur","L'adresse IP du poste","Le jour de la semaine",
 "Les attributs de la ressource décrivent l'objet : type, propriétaire, sensibilité."),
(1,"Quel est un exemple d'attribut d'environnement (contexte) ?","L'heure de la requête","Le propriétaire du document","Le nom du service du demandeur","La taille du fichier",
 "Le contexte comprend l'heure, le lieu, le niveau de risque de l'appareil."),
(2,"Quelle règle illustre ABAC ?","Permettre la lecture si service du sujet = service du document et heure entre 7 h et 20 h","Permettre à tous les comptables de lire","Permettre au propriétaire de tout faire","Interdire toute lecture",
 "La décision dépend de plusieurs attributs, y compris le contexte."),
(2,"Quel avantage ABAC a-t-il sur RBAC ?","Il exprime finement des règles dépendant du contexte sans multiplier les rôles","Il supprime les attributs","Il est plus simple à auditer","Il n'a pas besoin de politique",
 "Une règle générale remplace des dizaines de rôles spécifiques."),
(2,"Quel inconvénient ABAC présente-t-il ?","La complexité de la politique et la qualité des attributs à garantir","Il est incapable de refuser","Il n'a pas de journaux","Il n'utilise pas d'utilisateurs",
 "Si un attribut est faux ou périmé, la décision l'est aussi."),
(2,"Que signifie PDP en architecture XACML ?","Point de décision de la politique","Protocole de données personnelles","Plan de disponibilité des paiements","Pare-feu de périmètre",
 "Policy Decision Point : il évalue la politique et rend permis, refusé, etc."),
(2,"Que signifie PEP en architecture XACML ?","Point d'application de la politique","Protocole d'échange public","Programme d'exécution privé","Pare-feu d'entreprise",
 "Policy Enforcement Point : il intercepte la requête et applique la décision du PDP."),
(2,"Que signifie PIP en architecture XACML ?","Point d'information de la politique","Passerelle internet privée","Plan d'inventaire des permissions","Protocole d'identité publique",
 "Policy Information Point : il fournit les attributs manquants au PDP."),
(2,"Que signifie PAP en architecture XACML ?","Point d'administration de la politique","Point d'accès privilégié","Protocole d'authentification partagé","Plan d'audit périodique",
 "Policy Administration Point : l'endroit où l'on écrit et gère les politiques."),
(2,"Quel composant XACML intercepte la requête de l'utilisateur ?","Le PEP","Le PAP","Le PIP","Le PDP",
 "Le PEP est devant l'application et envoie la requête de décision au PDP."),
(2,"Quel composant XACML évalue les règles et rend la décision ?","Le PDP","Le PEP","Le PAP","Le PIP",
 "Le PDP applique la politique aux attributs fournis."),
(2,"Quel est l'ordre normal du flux XACML ?","PEP interroge PDP, PDP consulte PIP, PDP répond au PEP","PAP interroge PEP, PEP répond au PIP","PIP interroge PAP, PAP bloque PDP","PDP interroge l'utilisateur",
 "Le PEP ne décide pas : il applique la décision."),
(3,"Que signifie une réponse « NotApplicable » en XACML ?","Aucune règle ne s'applique à la requête","L'accès est permis","L'accès est refusé par une règle","Le PDP est arrêté",
 "Le PEP doit alors décider d'un comportement par défaut, de préférence le refus."),
(3,"Que signifie une réponse « Indeterminate » en XACML ?","Une erreur ou un attribut manquant empêche de décider","L'accès est permis sous condition","L'accès est refusé définitivement","La règle est supprimée",
 "Une bonne pratique est de refuser en cas d'indéterminé (fail-safe)."),
(2,"Qu'est-ce qu'un algorithme de combinaison de règles ?","Une méthode qui résout les conflits entre règles contradictoires","Un algorithme de chiffrement","Un outil de sauvegarde","Un type de rôle",
 "Par exemple « deny-overrides » : un refus l'emporte sur les permissions."),
(2,"Avec « deny-overrides », que se passe-t-il si une règle permet et une autre refuse ?","L'accès est refusé","L'accès est permis","La décision est aléatoire","Le système s'arrête",
 "Le refus est prioritaire : approche prudente."),
(2,"Avec « permit-overrides », que se passe-t-il si une règle permet et une autre refuse ?","L'accès est permis","L'accès est refusé","Aucun accès","Une alerte seulement",
 "Une permission suffit : approche plus ouverte, à utiliser avec précaution."),
(2,"Quelle norme du NIST décrit ABAC en détail ?","NIST SP 800-162","NIST SP 800-53 seulement","ISO 9001","RFC 791",
 "La publication (2014) définit les concepts et les considérations d'ABAC."),
(2,"Qu'est-ce que PBAC ?","Contrôle d'accès fondé sur des politiques exprimées de façon centralisée","Contrôle par mot de passe","Contrôle par badge","Contrôle par paquet réseau",
 "PBAC met la politique, souvent déclarative, au centre de la décision."),
(2,"Quel format est un langage de politique ABAC déclaratif standard ?","XACML","CSV","JPEG","SMTP",
 "Extensible Access Control Markup Language, norme OASIS."),
(2,"Quel outil moderne permet d'écrire des politiques d'autorisation sous forme de code ?","Open Policy Agent (langage Rego)","Un tableur","Un éditeur d'images","Un client de messagerie",
 "OPA découple la décision d'autorisation du code applicatif."),
(3,"Pourquoi découpler la décision d'autorisation du code de l'application ?","Pour changer la politique sans redéployer l'application","Pour supprimer les journaux","Pour accélérer l'écran","Pour éviter les utilisateurs",
 "La politique devient une donnée gouvernée, versionnée et testable."),
(2,"Un attribut « niveau de risque de l'appareil » appartient à :","Le contexte (environnement)","La ressource","Le sujet uniquement","L'action",
 "Il décrit les circonstances de l'accès."),
(3,"Une règle : « permis si le niveau d'habilitation ≥ la classification de la ressource ET le service est identique ». Que représente-t-elle ?","Un mélange de MAC et d'attributs","Un simple DAC","Un RBAC pur","Une ACL",
 "ABAC permet d'exprimer des règles de type MAC ou DAC, ou des combinaisons."),
(2,"Qui doit garantir la fiabilité des attributs utilisés par ABAC ?","Les sources autoritatives (RH, annuaire, inventaire)","L'utilisateur","Le hasard","Le navigateur",
 "La gouvernance des attributs est une condition de réussite."),
(3,"Quel risque survient si l'utilisateur peut modifier son propre attribut « service » ?","Il peut s'octroyer l'accès à d'autres ressources","Aucun risque","Un chiffrement","Une panne réseau",
 "Un attribut falsifiable rend la politique contournable."),
(2,"Comment appelle-t-on la décision de ne pas fournir d'accès par défaut ?","Refus par défaut","Permis par défaut","Délégation","Héritage",
 "Elle limite les conséquences d'une règle manquante."),
(2,"Quelle différence entre RBAC et ABAC concernant la granularité ?","ABAC est généralement plus fin","RBAC est toujours plus fin","Ils sont identiques","ABAC ne gère que des fichiers",
 "ABAC peut tenir compte d'attributs variés ; RBAC se limite aux rôles."),
(3,"Quel modèle est le plus adapté à une règle « un médecin voit uniquement les patients de son service pendant sa garde » ?","ABAC","DAC","MAC multi-niveaux","Capacités seules",
 "Elle combine fonction, service, relation de soin et temps."),
(2,"Qu'est-ce qu'une obligation en XACML ?","Une action à exécuter en même temps que l'application de la décision (par exemple journaliser)","Un devoir légal","Un type de rôle","Un chiffrement",
 "Les obligations complètent la décision : notifier, journaliser, filtrer."),
(2,"Quel avantage tire-t-on d'un PDP centralisé ?","Une politique cohérente dans plusieurs applications","Moins de journaux","Aucune politique","Suppression des attributs",
 "Un seul référentiel d'autorisation évite des règles divergentes."),
(3,"Quel inconvénient un PDP centralisé comporte-t-il ?","Une dépendance forte : sa panne peut bloquer les applications","Il supprime l'audit","Il interdit les rôles","Il n'a pas de politique",
 "Il faut prévoir disponibilité, cache et comportement en cas d'indisponibilité."),
(2,"Quel principe doit guider le comportement du PEP si le PDP est injoignable ?","Refuser par défaut, sauf politique de continuité explicitement définie","Autoriser tout","Redémarrer le PDP","Supprimer le PEP",
 "Fail-safe : on préfère l'indisponibilité à l'ouverture non contrôlée."),
(3,"Quelle règle exprime un « refus dynamique » basé sur un attribut contextuel ?","Refuser si l'appareil est non conforme, même avec le bon rôle","Autoriser si l'utilisateur est administrateur","Autoriser toujours","Refuser pour tous",
 "Les attributs de l'appareil complètent les droits statiques."),
(2,"Qu'appelle-t-on « accès conditionnel » ?","Des conditions de contexte (lieu, appareil, risque) exigées en plus de l'identité","Un accès sous condition d'âge","Un accès après sauvegarde","Un accès invité",
 "Les fournisseurs d'identité modernes l'implémentent comme un ABAC simplifié."),
(2,"Quel est un exemple de politique d'accès conditionnel ?","Exiger le MFA si la connexion vient d'un pays inhabituel","Autoriser tout le monde","Supprimer les comptes","Chiffrer les fichiers",
 "Le contexte déclenche une exigence supplémentaire."),
(3,"Pourquoi tester une politique ABAC avant son déploiement ?","Une règle erronée peut ouvrir ou bloquer massivement des accès","Pour supprimer les journaux","Pour choisir un logo","Pour réduire la mémoire",
 "Des jeux de tests et une simulation d'impact sont indispensables."),
(2,"Qu'est-ce qu'une politique « de refus explicite » ?","Une règle qui interdit un accès même si d'autres règles le permettent","Une règle qui permet","Une règle qui chiffre","Une règle qui archive",
 "Utile pour des interdictions absolues, comme l'export de données sensibles."),
(3,"Dans une politique, la règle A permet la lecture aux comptables et la règle B refuse l'export en dehors des heures de bureau. Un comptable lit à 22 h : résultat ?","Permis si la règle B ne concerne que l'export","Refusé car il est 22 h","Permis uniquement pour exporter","Indéterminé dans tous les cas",
 "La règle B ne s'applique pas à la lecture : seule l'action « exporter » est concernée."),
(2,"Quel attribut illustre le mieux une relation de confiance temporaire ?","Une délégation datée avec date de fin","Un nom de famille","Une couleur","Une taille de fichier",
 "Les accès délégués doivent expirer pour éviter qu'ils ne deviennent permanents."),
(2,"Qu'est-ce que l'« autorisation externalisée » ?","Confier la décision à un service dédié plutôt qu'au code de chaque application","Confier l'accès à un tiers sans contrat","Supprimer l'autorisation","Stocker les rôles dans un fichier texte",
 "Elle favorise la cohérence et l'audit centralisé."),
(1,"Quelle information est indispensable pour juger une règle ABAC ?","Les valeurs réelles des attributs au moment de la requête","Le nom de l'application","La couleur du site","L'âge du serveur",
 "Sans valeurs fiables, aucune règle ne peut être appliquée correctement."),
(3,"Quelle mesure limite la latence d'un PDP central consulté pour chaque requête ?","Un cache de décisions courtes et invalidées à chaque changement de politique","La suppression du PDP","Le partage de mot de passe","Un disque plus gros",
 "Le cache accélère mais doit rester cohérent avec les révocations."),
(3,"Que se passe-t-il si un cache de décisions n'est pas invalidé après la révocation d'un droit ?","L'utilisateur peut conserver l'accès pendant la durée du cache","Le droit est retiré immédiatement","Le serveur s'arrête","Les journaux sont supprimés",
 "Compromis à gérer : durée courte du cache ou notification de révocation."),
(2,"Quel modèle est le plus facile à auditer pour répondre à « qui a accès à quoi ? » ?","RBAC, par la lecture des rôles et de leurs membres","ABAC sans documentation","DAC sans journaux","Capacités sans inventaire",
 "ABAC est puissant mais demande des outils pour expliquer et simuler les décisions."),
(2,"Quelle approche mixte est courante en entreprise ?","RBAC pour le socle et ABAC pour les cas contextuels","DAC uniquement","MAC uniquement","Aucun contrôle",
 "On garde la lisibilité des rôles et on ajoute des attributs pour les exceptions."),
(3,"Quel risque l'ajout d'un nombre élevé de règles ABAC fait-il courir ?","Des règles contradictoires et une politique difficile à comprendre","Une réduction des utilisateurs","Un chiffrement involontaire","Une perte du réseau",
 "La gouvernance de la politique (revue, tests, propriétaires) devient indispensable."),
]
